'use client';
import Image from 'next/image';
import styles from '@/styles/ProfileImage.module.css';

const ProfileImage = () => {
  return (
    <div className={styles.container}>
      {/* Background Images */}
      <div
        className={`${styles.bgImage} ${styles.bgImage1}`}
        style={{ backgroundImage: "url('/bg1.jpg')" }}
      />
      <div
        className={`${styles.bgImage} ${styles.bgImage2}`}
        style={{ backgroundImage: "url('/bg2.jpg')" }}
      />
      <div
        className={`${styles.bgImage} ${styles.bgImage3}`}
        style={{ backgroundImage: "url('/bg3.jpg')" }}
      />

      {/* Main Profile Image */}
      <div className={styles.profileImage}>
        <Image
          src="/IMG_0509.JPG"
          alt="Profile Picture"
          layout="fill"
          objectFit="cover"
        />
      </div>
    </div>
  );
};

export default ProfileImage;